t","text":"A Bohicon plant filters "},{"type":"mathInline","attrs":{"latex":"V_n"}},{"type":"text","text":" m³ in month "},{"type":"mathInline","attrs":{"latex":"n"}},{"type":"text","text":" (geometric decay). [3]"}]},{"type":"graphBlock","attrs":{"spec":{"version":1,"title":"Monthly filtration volume","domain":{"xMin":0,"xMax":6,"yMin":250,"yMax":420,"gridStep":null,"showGrid":true,"showAxes":true,"showCoordinates":true,"showLegend":false,"showIntersections":false,"equalScale":false},"points":[{"id":"p0","x":1,"y":400,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p1","x":2,"y":360,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p2","x":3,"y":324,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p3","x":4,"y":291.6,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true}],"functions":[],"segments":[],"annotations":[],"strokes":[],"regions":[]}}},{"type":"paragraph","content":[{"type":"text","text":"**(i) "},{"type":"mathInline","attrs":{"latex":"r ="}},{"type":"text","text":"** ______ **; "},{"type":"mathInline","attrs":{"latex":"V_6 ="}},{"type":"text","text":"** ______   **(ii) "},{"type":"mathInline","attrs":{"latex":"S_6"}},{"type":"text","text":" (nearest m³) =** ______"}]}]},"e":"$r = 360/400 = 0.9$; $V_6 = 400(0.9)^5 = 236.196 \\approx 236.2$ m³. $S_6 = 400(1-0.9^6)/(1-0.9) = 1 874.24 \\approx 1 874$ m³.","m":3,"df":"hard","tp":"Geometric decay","st":"water filtration","cfg":{"question_number":30,"paper_question_key":30,"paper_section":"A","myp_criterion":"D","criterion_label":"Criterion D — Applying mathematics in real-life contexts","criterion_title":"Applying mathematics in real-life contexts","difficulty_level":"advanced","marks":3,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","marking_breakdown":[{"label":"(i)","marks":2,"focus":"ratio and V6"},{"label":"(ii)","marks":1,"foc