ype":"text","text":" are plotted for "},{"type":"mathInline","attrs":{"latex":"n = 1..5"}},{"type":"text","text":", meeting at (4, 24)."}]},{"type":"graphBlock","attrs":{"spec":{"version":1,"title":"Arithmetic A_n and geometric G_n","domain":{"xMin":0,"xMax":6,"yMin":0,"yMax":52,"gridStep":null,"showGrid":true,"showAxes":true,"showCoordinates":false,"showLegend":true,"showIntersections":false,"equalScale":false},"functions":[{"id":"f0","expression":"40 - 4x","color":"#0a5c36","style":"solid","width":2,"label":"A_n","from":0,"to":6,"visible":true},{"id":"f1","expression":"3*2^(x-1)","color":"#b45309","style":"dashed","width":2,"label":"G_n","from":0,"to":6,"visible":true}],"points":[{"id":"p0","x":1,"y":36,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p1","x":1,"y":3,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p2","x":4,"y":24,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p3","x":5,"y":48,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true}],"segments":[],"annotations":[],"strokes":[],"regions":[]}}},{"type":"paragraph","content":[{"type":"text","text":"**(a)** **Derive** simplified explicit formulas for "},{"type":"mathInline","attrs":{"latex":"A_n"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"G_n"}},{"type":"text","text":" from the graph, and **verify** algebraically that "},{"type":"mathInline","attrs":{"latex":"A_4 = G_4 = 24"}},{"type":"text","text":". [4]\n**(b)** **Find** the term number "},{"type":"mathInline","attrs":{"latex":"n"}},{"type":"text","text":" and value of the first negative term of "},{"type":"mathInline","attrs":{"latex":"A_n"}},{"type":"text","text":", and **evaluate** the arithmetic sum "},{"type":"mathInline","attrs":{"latex":"S_{20}"}},{"type":"text","text":" of "},{"type":"mathInline","attrs":{"latex":"A_n"}},{"type":"text","text":". [3]\n**(c)** **Evaluate** the exact geometric sum "},{"type":"mathInline","attrs":{"latex":"S_{10}"}},{"type":"text","text":" of "},{"type":"mathInline","attrs":{"latex":"G_n"}},{"type":"text","text":", and **find** the smallest integer "},{"type":"mathInline","attrs":{"latex":"n"}},{"type":"text","text":" for which "},{"type":"mathInline","attrs":{"latex":"G_n > 1 500"}},{"type":"text","text":". [3]"}]}]},"e":"(a) From (1,36) and (4,24), $d=(24-36)/3=-4$, so $A_n=36-4(n-1)=40-4n$. From (1,3) and (4,24), $r=2$, so $G_n=3\\cdot2^{n-1}$. At $n=4$, $A_4=24$ and $G_4=3(8)=24$.\n(b) $40-4n<0$ gives $n>10$, so the first negative term is $A_{11}=-4$. $S_{20}=\\frac{20}{2}(36-40)=-40$.\n(c) $S_{10}=3(2^{10}-1)=3 069$. $3\\cdot2^{n-1}>1500$ requires $2^{n-1}>500$; since $2^8=256$ and $2^9=512$, $n-1=9$, so $n=10$.","m":10,"df":"hard","tp":"Intersecting sequences & series","st":"arithmetic and geometric models","cfg":{"question_number":1,"paper_question_key":31,"paper_section":"B","myp_criterion":"A","criterion_label":"Criterion A — Knowing and understanding","criterion_title":"Knowing and understanding","difficulty_level":"advanced","marks":10,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","marking_breakdown":[{"label":"(a)","marks":4,"focus":"two formulas and verification"},{"label":"(b)","marks":3,"focus":"first negative term and S20"},{"label":"(c)","marks":3,"focus":"S10 and threshold"}],"parts":[{"id":"a1","label":"(a) A_n","prompt":"Simplified explicit formula for A_n","kind":"expression","points":1,"hints":["Re-read what (a) A_n is asking you to find.","Use the data and method named in the question for (a) A_n."],"accepted":["40-4n","36-4(n-1)"]},{"id":"a2","label":"(a) G_n","prompt":"Simplified explicit formula for G_n","kind":"expression","points":1,"hints":["Re-read what (a) G_n is asking you to find.","Use the data and method named in the question for (a) G_n."],"accepted":["3*2^(n-1)","3(2)^(n-1)","3×2^(n-1)"]},{"id":"a3","label":"(a) verification","prompt":"Verification that A4 = G4 = 24","kind":"text","points":1,"hints":["Re-read what (a) verification is asking you to find.","Use the data and method named in the question for (a) verification."],"accepted":["A4 = 40 - 16 = 24 and G4 = 3 × 2^3 = 24","A4=24, G4=3(8)=24"],"keywords":[["a4","40","24"],["g4","3","8","24"]],"minKeywordGroups":2},{"id":"a4","label":"(a) derivation","prompt":"Working that derives the common difference and ratio from the graph","kind":"text","points":1,"hints":["Re-read what (a) derivation is asking you to find.","Use the data and method named in the question for (a) derivation."],"accepted":["d = -4 from (1,36) and (4,24); r = 2 from (1,3) and (4,24)","A_n has d=-4 and G_n has r=2"],"keywords":[["d","-4"],["r","2"]],"minKeywordGroups":2},{"id":"b1","label":"(b) first negative","prompt":"Term number and value of the first negative term of A_n","kind":"text","points":1,"hints":["Re-read what (b) first negative is asking you to find.","Use the data and method named in the question for (b) first negative."],"accepted":["n=11, A11=-4","11 and -4","A11 = -4"]},{"id":"b2","label":"(b) S20","prompt":"Arithmetic sum S20","kind":"numeric","points":1,"hints":["Re-read what (b) S20 is asking you to find.","Use the data and method named in the question for (b) S20."],"answer":-40,"tolerance":0},{"id":"b3","label":"(b) method","prompt":"Method: solve 40 - 4n < 0 and substitute into the sum formula","kind":"text","points":1,"hints":["Re-read what (b) method is asking you to find.","Use the data and method named in the question for (b) method."],"accepted":["40 - 4n < 0 gives n > 10; S20 = 20/2(36 + (-40)) = -40","n>10 and S20=10(-4)"],"keywords":[["n","10","11"],["s20","-40","sum"]],"minKeywordGroups":2},{"id":"c1","label":"(c) S10","prompt":"Exact geometric sum S10","kind":"numeric","points":1,"hints":["Re-read what (c) S10 is asking you to find.","Use the data and method named in the question for (c) S10."],"answer":3069,"tolerance":0},{"id":"c2","label":"(c) threshold","prompt":"Smallest integer n for which G_n > 1500","kind":"numeric","points":1,"hints":["Re-read what (c) threshold is asking you to find.","Use the data and method named in the question for (c) threshold."],"answer":10,"tolerance":0},{"id":"c3","label":"(c) method","prompt":"Method: solve 3 × 2^(n-1) > 1500 using powers of 2","kind":"text","points":1,"hints":["Re-read what (c) method is asking you to find.","Use the data and method named in the question for (c) method."],"accepted":["2^(n-1) > 500, and 2^9 = 512, so n = 10","n-1=9 therefore n=10"],"keywords":[["500"],["2^9","512"],["10"]],"minKeywordGroups":2}],"source":"myp5-grade10-sequences-version-c-2026-27"}},{"n":32,"t":"assess_parts","p":"**TASK 2 · CRITERION B — Investigating patterns [10 marks]**\n**2. Courtyard tile pattern & quadratic growth [10 mks]** Stage $n$ has an $n \\times (n+1)$ green core ($C_n$) bordered top and bottom by rows of $(n+1)$ pale tiles ($B_n$), giving total tiles $T_n = C_n + B_n$.\n\n[Figure: Courtyard tile patterns: pale rows above and below the green core]\n**(a)** **Tabulate** $B_n$, $C_n$ and $T_n$ for $1 \\le n \\le 5$, and use first and second differences to **classify** $B_n$ and $T_n$. [4]\n**(b)** **Write** expanded explicit formulas for $B_n$, $C_n$ and $T_n$ in terms of $n$, and **state** the stage where $C_n = B_n$. [3]\n**(c)** **Form and solve** a quadratic equation to find which stage requires exactly $T_n = 210$ tiles. [3]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"**TASK 2 · CRITERION B — Investigating patterns [10 marks]**"}]},{"type":"paragraph","content":[{"type":"text","text":"**2. Courtyard tile pattern & quadratic growth [10 mks]** Stage "},{"type":"mathInline","attrs":{"latex":"n"}},{"type":"text","text":" has an "},{"type":"mathInline","attrs":{"latex":"n \\times (n+1)"}},{"type":"text","text":" green core ("},{"type":"mathInline","attrs":{"latex":"C_n"}},{"type":"text","text":") bordered top and bottom by rows of "},{"type":"mathInline","attrs":{"latex":"(n+1)"}},{"type":"text","text":" pale tiles ("},{"type":"mathInline","attrs":{"latex":"B_n"}},{"type":"text","text":"), giving total tiles "},{"type":"mathInline","attrs":{"latex":"T_n = C_n + B_n"}},{"type":"text","text":"."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"version":1,"kind":"grid_pattern","title":"Courtyard tile patterns: pale rows above and below the green core","gridPatterns":[{"label":"Stage 1 · 6 tiles","cols":2,"rows":3,"style":"top_bottom_border"},{"label":"Stage 2 · 12 tiles","cols":3,"rows":4,"style":"top_bottom_border"},{"label":"Stage 3 · 20 tiles","cols":4,"rows":5,"style":"top_bottom_border"}]}}},{"type":"paragraph","content":[{"type":"text","text":"**(a)** **Tabulate** "},{"type":"mathInline","attrs":{"latex":"B_n"}},{"type":"text","text":", "},{"type":"mathInline","attrs":{"latex":"C_n"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"T_n"}},{"type":"text","text":" for "},{"type":"mathInline","attrs":{"latex":"1 \\le n \\le 5"}},{"type":"text","text":", and use first and second differences to **classify** "},{"type":"mathInline","attrs":{"latex":"B_n"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"T_n"}},{"type":"text","text":". [4]\n**(b)** **Write** expanded explicit formulas for "},{"type":"mathInline","attrs":{"latex":"B_n"}},{"type":"text","text":", "},{"type":"mathInline","attrs":{"latex":"C_n"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"T_n"}},{"type":"text","text":" in terms of "},{"type":"mathInline","attrs":{"latex":"n"}},{"type":"text","text":", and **state** the stage where "},{"type":"mathInline","attrs":{"latex":"C_n = B_n"}},{"type":"text","text":". [3]\n**(c)** **Form and solve** a quadratic equation to find which stage requires exactly "},{"type":"mathInline","attrs":{"latex":"T_n = 210"}},{"type":"text","text":" tiles. [3]"}]}]},"e":"(a) Stage 1–5: B = 4, 6, 8, 10, 12; C = 2, 6, 12, 20, 30; T = 6, 12, 20, 30, 42. B has constant first difference 2 (linear/arithmetic); T has first differences 6, 8, 10, 12 and constant second difference 2 (quadratic).\n(b) $B_n = 2n+2$, $C_n = n^2+n$, $T_n = n^2+3n+2$. $C_n=B_n$ gives $n^2-n-2=0$, so $n=2$ (both 6).\n(c) $n^2+3n+2=210$ gives $n^2+3n-208=(n-13)(n+16)=0$, so stage 13.","m":10,"df":"hard","tp":"Courtyard tile pattern & quadratic growth","st":"linear and quadratic models","cfg":{"question_number":2,"paper_question_key":32,"paper_section":"B","myp_criterion":"B","criterion_label":"Criterion B — Investigating patterns","criterion_title":"Investigating patterns","difficulty_level":"advanced","marks":10,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","marking_breakdown":[{"label":"(a) table","marks":2,"focus":"three sequences for n=1..5"},{"label":"(a) classification","marks":2,"focus":"first/second differences"},{"label":"(b) formulas","marks":2,"focus":"three explicit formulas"},{"label":"(b) equality","marks":1,"focus":"stage"},{"label":"(c) equation","marks":2,"focus":"form and solve"},{"label":"(c) stage","marks":1,"focus":"positive root"}],"parts":[{"id":"a1","label":"(a) B_n","prompt":"Values of B_n for n = 1 to 5","kind":"text","points":1,"hints":["Re-read what (a) B_n is asking you to find.","Use the data and method named in the question for (a) B_n."],"accepted":["4, 6, 8, 10, 12"]},{"id":"a2","label":"(a) C_n and T_n","prompt":"Values of C_n and T_n for n = 1 to 5","kind":"text","points":1,"hints":["Re-read what (a) C_n and T_n is asking you to find.","Use the data and method named in the question for (a) C_n and T_n."],"accepted":["C: 2, 6, 12, 20, 30; T: 6, 12, 20, 30, 42","2,6,12,20,30 and 6,12,20,30,42"]},{"id":"a3","label":"(a) B_n classification","prompt":"Classify B_n using differences","kind":"text","points":1,"hints":["Re-read what (a) B_n classification is asking you to find.","Use the data and method named in the question for (a) B_n classification."],"accepted":["Linear/arithmetic, constant first difference 2"],"keywords":[["linear","arithmetic"],["first difference","2","constant"]],"minKeywordGroups":2},{"id":"a4","label":"(a) T_n classification","prompt":"Classify T_n using differences","kind":"text","points":1,"hints":["Re-read what (a) T_n classification is asking you to find.","Use the data and method named in the question for (a) T_n classification."],"accepted":["Quadratic, first differences 6,8,10,12 and constant second difference 2"],"keywords":[["quadratic"],["second difference","2","constant"]],"minKeywordGroups":2},{"id":"b1","label":"(b) formulas","prompt":"Expanded explicit formulas for B_n, C_n and T_n","kind":"expression","points":1,"hints":["Re-read what (b) formulas is asking you to find.","Use the data and method named in the question for (b) formulas."],"accepted":["B_n=2n+2, C_n=n^2+n, T_n=n^2+3n+2","(2n+2, n^2+n, n^2+3n+2)"]},{"id":"b2","label":"(b) C_n formula","prompt":"Expanded formula for C_n","kind":"expression","points":1,"hints":["Re-read what (b) C_n formula is asking you to find.","Use the data and method named in the question for (b) C_n formula."],"accepted":["n^2+n","n(n+1)"]},{"id":"b3","label":"(b) equality","prompt":"Stage where C_n = B_n","kind":"numeric","points":1,"hints":["Re-read what (b) equality is asking you to find.","Use the data and method named in the question for (b) equality."],"answer":2,"tolerance":0},{"id":"c1","label":"(c) equation","prompt":"Quadratic equation formed from T_n = 210","kind":"expression","points":1,"hints":["Re-read what (c) equation is asking you to find.","Use the data and method named in the question for (c) equation."],"accepted":["n^2+3n-208=0","n^2+3n+2=210"]},{"id":"c2","label":"(c) stage","prompt":"Stage requiring exactly 210 tiles","kind":"numeric","points":2,"hints":["Re-read what (c) stage is asking you to find.","Use the data and method named in the question for (c) stage."],"answer":13,"tolerance":0}],"source":"myp5-grade10-sequences-version-c-2026-27"}},{"n":33,"t":"assess_parts","p":"**TASK 3 · CRITERION C — Communicating [10 marks]**\n**3. Graphical & symbolic sequence communication [10 mks]** Discrete sequences $P_n$ (−24, 12, −6, 3, −1.5) and $R_n$ (9, 4, 1, 0, 1) are plotted below:\n\n[Figure: Panel I (P_n)]\n\n[Figure: Panel II (R_n)]\n**(a)** **Classify** Panel I ($P_n$) and Panel II ($R_n$), citing one distinct visual feature from each coordinate graph. [3]\n**(b)** Using proper subscript notation, **state** both an explicit formula and a complete recursive definition (with initial term) for $P_n$ and $R_n$. [4]\n**(c)** To sum $8 + 13 + 18 + \\ldots + 93$, Malik writes $n = \\frac{93-8}{5} = 17$ and $S_{17} = 858.5$; to sum 6 terms of $5 + 10 + 20 + \\ldots$, Amina writes $S_6 = \\frac{5(1-2^5)}{1-2} = 155$. **Explain** each student''s error and **compute** both correct sums. [3]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"**TASK 3 · CRITERION C — Communicating [10 marks]**"}]},{"type":"paragraph","content":[{"type":"text","text":"**3. Graphical & symbolic sequence communication [10 mks]** Discrete sequences "},{"type":"mathInline","attrs":{"latex":"P_n"}},{"type":"text","text":" (−24, 12, −6, 3, −1.5) and "},{"type":"mathInline","attrs":{"latex":"R_n"}},{"type":"text","text":" (9, 4, 1, 0, 1) are plotted below:"}]},{"type":"graphBlock","attrs":{"spec":{"version":1,"title":"Panel I (P_n)","domain":{"xMin":0,"xMax":6,"yMin":-27,"yMax":15,"gridStep":null,"showGrid":true,"showAxes":true,"showCoordinates":true,"showLegend":false,"showIntersections":false,"equalScale":false},"points":[{"id":"p0","x":1,"y":-24,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p1","x":2,"y":12,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p2","x":3,"y":-6,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p3","x":4,"y":3,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p4","x":5,"y":-1.5,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true}],"functions":[{"id":"fn-1","to":5,"from":1,"color":"#0a5c36","label":"P_n","style":"solid","width":2,"visible":true,"expression":"-24*(-0.5)^(x-1)"}],"segments":[],"annotations":[],"strokes":[{"id":"stroke-1","points":[{"x":1,"y":-24},{"x":2,"y":12},{"x":3,"y":-6},{"x":4,"y":3},{"x":5,"y":-1.5}],"color":"#0a5c36","width":2,"visible":true}],"regions":[]}}},{"type":"graphBlock","attrs":{"spec":{"version":1,"title":"Panel II (R_n)","domain":{"xMin":0,"xMax":6,"yMin":-1,"yMax":10,"gridStep":null,"showGrid":true,"showAxes":true,"showCoordinates":true,"showLegend":false,"showIntersections":false,"equalScale":false},"points":[{"id":"p0","x":1,"y":9,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p1","x":2,"y":4,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p2","x":3,"y":1,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p3","x":4,"y":0,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true},{"id":"p4","x":5,"y":1,"label":"","color":"#0a5c36","showCoordinates":true,"open":false,"visible":true}],"functions":[{"id":"fn-1","to":5,"from":1,"color":"#b45309","label":"R_n","style":"solid","width":2,"visible":true,"expression":"(x-4)^2"}],"segments":[],"annotations":[],"strokes":[],"regions":[]}}},{"type":"paragraph","content":[{"type":"text","text":"**(a)** **Classify** Panel I ("},{"type":"mathInline","attrs":{"latex":"P_n"}},{"type":"text","text":") and Panel II ("},{"type":"mathInline","attrs":{"latex":"R_n"}},{"type":"text","text":"), citing one distinct visual feature from each coordinate graph. [3]\n**(b)** Using proper subscript notation, **state** both an explicit formula and a complete recursive definition (with initial term) for "},{"type":"mathInline","attrs":{"latex":"P_n"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"R_n"}},{"type":"text","text":". [4]\n**(c)** To sum "},{"type":"mathInline","attrs":{"latex":"8 + 13 + 18 + \\ldots + 93"}},{"type":"text","text":", Malik writes "},{"type":"mathInline","attrs":{"latex":"n = \\frac{93-8}{5} = 17"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"S_{17} = 858.5"}},{"type":"text","text":"; to sum 6 terms of "},{"type":"mathInline","attrs":{"latex":"5 + 10 + 20 + \\ldots"}},{"type":"text","text":", Amina writes "},{"type":"mathInline","attrs":{"latex":"S_6 = \\frac{5(1-2^5)}{1-2} = 155"}},{"type":"text","text":". **Explain** each student''s error and **compute** both correct sums. [3]"}]}]},"e":"(a) P_n is an alternating geometric sequence: points alternate in sign across the horizontal axis and halve in distance from zero (r = −1/2). R_n is quadratic: the points lie on a U-shaped parabola with minimum vertex at (4, 0) and symmetry R3 = R5 = 1.\n(b) P_n = −24(−1/2)^(n−1); P1 = −24, Pn+1 = −1/2 Pn. R_n = (n−4)^2 = n^2−8n+16; R1 = 9, Rn+1 = Rn + 2n − 7.\n(c) Malik omitted +1 when counting terms: from 8 + 5(n−1) = 93, n−1 = 17, so n = 18 and S18 = 9(8+93) = 909. Amina used n−1 = 5 as the exponent instead of the 6 terms: S6 = 5(2^6−1)/(2−1) = 315.","m":10,"df":"hard","tp":"Graphical & symbolic sequence communication","st":"classification, explicit and recursive rules, error analysis","cfg":{"question_number":3,"paper_question_key":33,"paper_section":"B","myp_criterion":"C","criterion_label":"Criterion C — Communicating","criterion_title":"Communicating","difficulty_level":"advanced","marks":10,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","marking_breakdown":[{"label":"(a)","marks":3,"focus":"two classifications and visual features"},{"label":"(b)","marks":4,"focus":"four rules"},{"label":"(c)","marks":3,"focus":"two errors and two sums"}],"parts":[{"id":"a1","label":"(a) P_n","prompt":"Classification of P_n and one distinct visual feature","kind":"text","points":1,"hints":["Re-read what (a) P_n is asking you to find.","Use the data and method named in the question for (a) P_n."],"accepted":["Alternating geometric; points alternate above and below the n-axis while halving","Geometric with r=-1/2; the points alternate signs and halve"],"keywords":[["geometric","alternating"],["alternate","sign","halve","axis"]],"minKeywordGroups":2},{"id":"a2","label":"(a) R_n","prompt":"Classification of R_n and one distinct visual feature","kind":"text","points":1,"hints":["Re-read what (a) R_n is asking you to find.","Use the data and method named in the question for (a) R_n."],"accepted":["Quadratic; U-shaped parabola with minimum vertex (4,0) and symmetry R3=R5","Quadratic; points form a parabola with vertex at (4,0)"],"keywords":[["quadratic","parabola"],["vertex","4","0","symmetry","u-shaped"]],"minKeywordGroups":2},{"id":"a3","label":"(a) feature","prompt":"A second distinct visual feature supporting the classifications","kind":"text","points":1,"hints":["Re-read what (a) feature is asking you to find.","Use the data and method named in the question for (a) feature."],"accepted":["P_n alternates in sign and halves; R_n has a minimum at (4,0)","The geometric terms approach zero and alternate; the quadratic is symmetric about n=4"],"keywords":[["halve","zero","alternate","sign"],["minimum","symmetry","vertex","4"]],"minKeywordGroups":2},{"id":"b1","label":"(b) P explicit","prompt":"Explicit formula for P_n","kind":"expression","points":1,"hints":["Re-read what (b) P explicit is asking you to find.","Use the data and method named in the question for (b) P explicit."],"accepted":["-24(-1/2)^(n-1)","-24*(-0.5)^(n-1)"]},{"id":"b2","label":"(b) P recursive","prompt":"Recursive definition for P_n with initial term","kind":"text","points":1,"hints":["Re-read what (b) P recursive is asking you to find.","Use the data and method named in the question for (b) P recursive."],"accepted":["P1=-24, Pn+1=(-1/2)Pn","P_1 = -24, P_{n+1} = -0.5 P_n"]},{"id":"b3","label":"(b) R explicit","prompt":"Explicit formula for R_n","kind":"expression","points":1,"hints":["Re-read what (b) R explicit is asking you to find.","Use the data and method named in the question for (b) R explicit."],"accepted":["(n-4)^2","n^2-8n+16"]},{"id":"b4","label":"(b) R recursive","prompt":"Recursive definition for R_n with initial term","kind":"text","points":1,"hints":["Re-read what (b) R recursive is asking you to find.","Use the data and method named in the question for (b) R recursive."],"accepted":["R1=9, Rn+1=Rn+2n-7","R_1 = 9, R_{n+1} = R_n + 2n - 7"]},{"id":"c1","label":"(c) Malik error","prompt":"Malik''s error","kind":"text","points":1,"hints":["Re-read what (c) Malik error is asking you to find.","Use the data and method named in the question for (c) Malik error."],"accepted":["He omitted +1 when counting terms; there are 18 terms, not 17","n-1=17 so n=18 terms"],"keywords":[["18","term"],["+1","count","omitted"]],"minKeywordGroups":2},{"id":"c2","label":"(c) Malik sum","prompt":"Correct arithmetic sum","kind":"numeric","points":1,"hints":["Re-read what (c) Malik sum is asking you to find.","Use the data and method named in the question for (c) Malik sum."],"answer":909,"tolerance":0},{"id":"c3","label":"(c) Amina","prompt":"Amina''s error and the correct geometric sum","kind":"text","points":1,"hints":["Re-read what (c) Amina is asking you to find.","Use the data and method named in the question for (c) Amina."],"accepted":["She used exponent 5 instead of 6; S6 = 5(2^6-1) = 315","The exponent must be n=6; correct sum 315"],"keywords":[["exponent","6","n-1","five"],["315"]],"minKeywordGroups":2}],"source":"myp5-grade10-sequences-version-c-2026-27"}},{"n":34,"t":"assess_parts","p":"**TASK 4 · CRITERION D — Applying in real-life contexts [10 marks]**\n**4. Cotonou port cold-storage solar array & service plans [10 mks]** A Port of Cotonou cold-storage facility generates 600 MWh of solar electricity in Year 1, declining by 4% per year.\n**(a)** **State** the geometric ratio $r$, **calculate** Year 6 output $E_6$ (1 d.p.), and **compute** 10-year cumulative output $S_{10}$ (1 d.p.) against a 5 000 MWh target. [4]\n**(b)** Two 6-year maintenance contracts are offered: **Option X** costs 300 000 FCFA in Year 1 (+40 000 FCFA/yr); **Option Y** costs 220 000 FCFA in Year 1 (+25%/yr, r = 1.25). **Calculate** $S_6$ for both options (nearest FCFA). [4]\n**(c)** **Compare** 3-year totals ($S_3$) versus 6-year totals ($S_6$) and **recommend** the lower-cost option for each horizon. [2]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"**TASK 4 · CRITERION D — Applying in real-life contexts [10 marks]**"}]},{"type":"paragraph","content":[{"type":"text","text":"**4. Cotonou port cold-storage solar array & service plans [10 mks]** A Port of Cotonou cold-storage facility generates 600 MWh of solar electricity in Year 1, declining by 4% per year."}]},{"type":"paragraph","content":[{"type":"text","text":"**(a)** **State** the geometric ratio "},{"type":"mathInline","attrs":{"latex":"r"}},{"type":"text","text":", **calculate** Year 6 output "},{"type":"mathInline","attrs":{"latex":"E_6"}},{"type":"text","text":" (1 d.p.), and **compute** 10-year cumulative output "},{"type":"mathInline","attrs":{"latex":"S_{10}"}},{"type":"text","text":" (1 d.p.) against a 5 000 MWh target. [4]\n**(b)** Two 6-year maintenance contracts are offered: **Option X** costs 300 000 FCFA in Year 1 (+40 000 FCFA/yr); **Option Y** costs 220 000 FCFA in Year 1 (+25%/yr, r = 1.25). **Calculate** "},{"type":"mathInline","attrs":{"latex":"S_6"}},{"type":"text","text":" for both options (nearest FCFA). [4]\n**(c)** **Compare** 3-year totals ("},{"type":"mathInline","attrs":{"latex":"S_3"}},{"type":"text","text":") versus 6-year totals ("},{"type":"mathInline","attrs":{"latex":"S_6"}},{"type":"text","text":") and **recommend** the lower-cost option for each horizon. [2]"}]}]},"e":"(a) r = 0.96. E6 = 600(0.96)^5 = 489.2 MWh. S10 = 600(1−0.96^10)/0.04 = 5 027.5 MWh, which exceeds 5 000 MWh by 27.5 MWh.\n(b) X: S6 = 6/2[2(300000)+5(40000)] = 2 400 000 FCFA. Y: S6 = 220000(1.25^6−1)/0.25 = 2 476 934 FCFA.\n(c) S3,X = 3/2[600000+80000] = 1 020 000 FCFA; S3,Y = 880000(1.25^3−1) = 838 750 FCFA. Choose Y for 3 years (saves 181 250 FCFA); choose X for 6 years (saves 76 934 FCFA).","m":10,"df":"hard","tp":"Cotonou port cold-storage solar array & service plans","st":"geometric models and financial comparison","cfg":{"question_number":4,"paper_question_key":34,"paper_section":"B","myp_criterion":"D","criterion_label":"Criterion D — Applying mathematics in real-life contexts","criterion_title":"Applying mathematics in real-life contexts","difficulty_level":"advanced","marks":10,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","marking_breakdown":[{"label":"(a) r","marks":1,"focus":""},{"label":"(a) E6","marks":1,"focus":""},{"label":"(a) S10","marks":1,"focus":"sum"},{"label":"(a) target decision","marks":1,"focus":""},{"label":"(b) X","marks":2,"focus":"sum"},{"label":"(b) Y","marks":2,"focus":"sum"},{"label":"(c) S3","marks":1,"focus":"both options"},{"label":"(c) recommendation","marks":1,"focus":"both horizons"}],"parts":[{"id":"r","label":"(a) ratio","prompt":"Geometric ratio r","kind":"numeric","points":1,"hints":["Re-read what (a) ratio is asking you to find.","Use the data and method named in the question for (a) ratio."],"answer":0.96,"tolerance":0},{"id":"e6","label":"(a) E6","prompt":"Year 6 output (1 d.p.)","kind":"numeric","points":1,"hints":["Re-read what (a) E6 is asking you to find.","Use the data and method named in the question for (a) E6."],"unit":"MWh","answer":489.2,"tolerance":0.05},{"id":"s10","label":"(a) S10","prompt":"10-year cumulative output (1 d.p.)","kind":"numeric","points":1,"hints":["Re-read what (a) S10 is asking you to find.","Use the data and meth